create table public."Users" (
  "Id" bigint generated by default as identity not null,
  "Name" character varying null,
  "Email" character varying null,
  "PasswordHash" character varying null,
  "NickName" character varying null,
  "Picture" character varying null,
  "PhoneNumber" character varying null,
  "StatusId" bigint null,
  "EmailConfirmed" boolean null,
  "PhoneConfirmed" boolean null,
  "TermsConfirmed" boolean null,
  "Systema" boolean null,
  "CorporationId" bigint null,
  constraint users_pkey primary key ("Id"),
  constraint "Users_CorporationId_fkey" foreign KEY ("CorporationId") references "Corporations" (id)
) TABLESPACE pg_default;